originalCss:
:root {
    --bg: #07111e;
    --panel: #0c1a2d;
    --panel2: #10213a;
    --border: #1f3354;
    --text: #e6edf7;
    --dim: #c7d6ec;
    --faint: #9cb0cf;
    --accent: #7c9eff;
    --accent2: #a8bfff;
    --sidebar: 288px;
    --sans:
        'Noto Sans JP', 'Hiragino Kaku Gothic ProN', 'Yu Gothic', Meiryo, sans-serif;
    --mono:
        'JetBrains Mono', ui-monospace, SFMono-Regular, Menlo, Consolas, 'Noto Sans JP',
        monospace;
}
* {
    box-sizing: border-box;
}
html {
    scroll-behavior: smooth;
    overflow-x: hidden;
}
body {
    margin: 0;
    background: var(--bg);
    color: var(--text);
    font-family: var(--sans);
    font-size: 16px;
    line-height: 1.85;
    overflow-x: hidden;
    -webkit-font-smoothing: antialiased;
}
.sidebar {
    position: fixed;
    left: 0;
    top: 0;
    bottom: 0;
    width: var(--sidebar);
    background: #091524;
    border-right: 1px solid var(--border);
    overflow-y: auto;
    padding: 22px 14px 40px;
    z-index: 30;
}
.sidebar-title {
    font-weight: 800;
    font-size: 13px;
    letter-spacing: 0.06em;
    color: var(--accent);
    padding: 0 10px 14px;
    border-bottom: 1px solid var(--border);
    margin-bottom: 12px;
}
.nav-list,
.nav-list ul {
    list-style: none;
    margin: 0;
    padding: 0;
}
.nav-list a {
    display: block;
    color: var(--dim);
    text-decoration: none;
    font-size: 13.5px;
    line-height: 1.5;
    padding: 6px 10px;
    border-radius: 8px;
    border-left: 2px solid transparent;
}
.nav-list a:hover {
    background: #0f2038;
    color: #fff;
}
.nav-list a.active {
    background: #12284a;
    color: #fff;
    border-left-color: var(--accent);
}
.nav-h2 > a {
    font-weight: 700;
    margin-top: 6px;
}
.nav-h3 a {
    font-size: 12.5px;
    color: var(--faint);
    padding-left: 22px;
}
.main {
    margin-left: var(--sidebar);
    padding: 40px 48px 80px;
    min-width: 0;
}
.hero {
    position: relative;
    padding: 34px 34px 28px;
    border: 1px solid var(--border);
    border-radius: 18px;
    background: linear-gradient(180deg, #0d1d35, #0a1626);
    margin-bottom: 28px;
    overflow: hidden;
}
.hero::before {
    content: '';
    position: absolute;
    right: -80px;
    top: -80px;
    width: 340px;
    height: 340px;
    background: radial-gradient(circle, rgba(124, 158, 255, 0.28), transparent 68%);
    pointer-events: none;
}
.eyebrow {
    display: inline-block;
    font-size: 12px;
    font-weight: 700;
    letter-spacing: 0.05em;
    color: var(--accent2);
    border: 1px solid #2c4a86;
    background: #0f2447;
    border-radius: 999px;
    padding: 3px 14px;
    margin-bottom: 14px;
    position: relative;
}
.hero-title {
    margin: 0 0 8px;
    font-size: 28px;
    font-weight: 800;
    color: #fff;
    line-height: 1.4;
    position: relative;
}
.hero-sub {
    margin: 0 0 20px;
    color: var(--dim);
    font-size: 15px;
    position: relative;
}
.hero-meta {
    display: flex;
    flex-wrap: wrap;
    border-top: 1px solid var(--border);
    padding-top: 16px;
    position: relative;
}
.meta-item {
    padding: 0 24px;
    border-right: 1px solid var(--border);
    min-width: 0;
}
.meta-item:first-child {
    padding-left: 0;
}
.meta-item:last-child {
    border-right: 0;
}
.meta-label {
    font-size: 11px;
    letter-spacing: 0.08em;
    color: var(--faint);
    text-transform: uppercase;
}
.meta-value {
    font-size: 14.5px;
    color: var(--text);
    overflow-wrap: anywhere;
}
.meta-value a {
    color: var(--accent2);
}
h2 {
    font-size: 24px;
    font-weight: 800;
    color: #fff;
    margin: 56px 0 18px;
    padding: 0 0 10px 14px;
    border-bottom: 1px solid var(--border);
    border-left: 4px solid var(--accent);
    line-height: 1.5;
    scroll-margin-top: 20px;
}
h3 {
    font-size: 19px;
    font-weight: 700;
    color: var(--accent2);
    margin: 34px 0 12px;
    scroll-margin-top: 20px;
}
p {
    margin: 0 0 14px;
    color: var(--text);
}
ul,
ol {
    padding-left: 1.4em;
    margin: 0 0 16px;
}
li {
    margin: 4px 0;
}
a {
    color: var(--accent2);
    overflow-wrap: anywhere;
}
code {
    font-family: var(--mono);
    font-size: 0.88em;
    background: #102340;
    color: #cfe0ff;
    padding: 0.12em 0.42em;
    border-radius: 6px;
    overflow-wrap: break-word;
    word-break: break-word;
}
.table-scroll {
    overflow-x: auto;
    margin: 16px 0 22px;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: var(--panel);
}
table {
    border-collapse: collapse;
    width: 100%;
    font-size: 14.5px;
    line-height: 1.7;
}
th {
    background: #112444;
    color: #fff;
    font-weight: 700;
    text-align: left;
    white-space: nowrap;
}
th,
td {
    padding: 10px 14px;
    border-bottom: 1px solid var(--border);
    vertical-align: top;
}
tr:last-child td {
    border-bottom: 0;
}
td {
    color: var(--text);
    min-width: 90px;
}
tbody tr:hover td {
    background: #0d1f3a;
}
td code {
    white-space: normal;
}
td:first-child {
    min-width: 7.5em;
}
.code-block {
    position: relative;
    margin: 16px 0 22px;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: #08142a;
    overflow: hidden;
}
.code-lang {
    font-size: 11px;
    font-weight: 700;
    letter-spacing: 0.08em;
    color: var(--accent2);
    background: #0f2447;
    padding: 5px 14px;
    border-bottom: 1px solid var(--border);
}
pre {
    margin: 0;
    padding: 16px 18px;
    overflow-x: auto;
    font-family: var(--mono);
    font-size: 13.5px;
    line-height: 1.7;
    background: transparent;
}
pre code {
    background: transparent;
    padding: 0;
    color: #dbe6fb;
    font-size: inherit;
    word-break: normal;
    overflow-wrap: normal;
}
.tk-c {
    color: #6f87ad;
    font-style: italic;
}
.tk-s {
    color: #9fe0b0;
}
.tk-n {
    color: #ffcb8a;
}
.tk-k {
    color: #c4a7ff;
}
.callout {
    display: flex;
    gap: 14px;
    margin: 18px 0 22px;
    padding: 14px 18px;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: var(--panel);
}
.callout-icon {
    font-size: 20px;
    line-height: 1.7;
    flex: none;
}
.callout-body {
    min-width: 0;
}
.callout-body p {
    margin: 0 0 8px;
    color: var(--text);
}
.callout-body p:last-child {
    margin-bottom: 0;
}
.callout-tip {
    border-left: 4px solid #5fd3a1;
    background: #0b2227;
}
.callout-warn {
    border-left: 4px solid #ffb86b;
    background: #261d12;
}
.callout-note {
    border-left: 4px solid var(--accent);
    background: #0d1d3a;
}
.glossary {
    margin: 18px 0 26px;
    padding: 14px 20px 8px;
    border: 1px dashed #2c4a86;
    border-radius: 12px;
    background: #0a1a30;
}
.glossary-title {
    font-weight: 700;
    color: var(--accent2);
    margin-bottom: 6px;
    font-size: 15px;
}
.glossary ul {
    margin: 0 0 10px;
    font-size: 14.5px;
    color: var(--dim);
}
details {
    margin: 12px 0 16px;
    border: 1px solid var(--border);
    border-radius: 10px;
    background: var(--panel);
    padding: 10px 16px;
}
details summary {
    cursor: pointer;
    font-weight: 700;
    color: var(--accent2);
}
details[open] summary {
    margin-bottom: 8px;
}
.checklist-card {
    margin: 16px 0 22px;
    border: 1px solid var(--border);
    border-radius: 12px;
    background: var(--panel);
    padding: 14px 18px;
}
.checklist-progress {
    display: flex;
    align-items: center;
    gap: 12px;
    margin-bottom: 10px;
    font-size: 13px;
    color: var(--faint);
}
.cp-bar {
    flex: 1;
    height: 8px;
    border-radius: 999px;
    background: #112444;
    overflow: hidden;
}
.cp-fill {
    height: 100%;
    width: 0;
    background: linear-gradient(90deg, #5fd3a1, #7c9eff);
    transition: width 0.2s;
}
ul.checklist {
    list-style: none;
    padding: 0;
    margin: 0;
}
ul.checklist li {
    display: flex;
    gap: 10px;
    align-items: flex-start;
}
ul.checklist input {
    margin-top: 0.55em;
    accent-color: #7c9eff;
}
.mermaid-diagram {
    display: block;
    overflow-x: auto;
    margin: 20px 0 26px;
    padding: 20px;
    border: 1px solid var(--border);
    border-radius: 14px;
    background: #0a1626;
}
.mermaid-diagram svg {
    display: block;
    margin-left: auto;
    margin-right: auto;
    max-width: none;
    flex-shrink: 0;
    height: auto;
}
.mermaid-diagram foreignObject {
    overflow: visible;
}
.mermaid-diagram foreignObject div,
.mermaid-diagram foreignObject span,
.mermaid-diagram foreignObject p {
    white-space: normal !important;
    color: inherit;
    margin: 0;
}
.page-footer {
    margin-top: 60px;
    padding-top: 18px;
    border-top: 1px solid var(--border);
    color: var(--faint);
    font-size: 13px;
}
.sidebar-toggle {
    display: none;
    position: fixed;
    top: 12px;
    left: 12px;
    z-index: 50;
    background: #12284a;
    color: #fff;
    border: 1px solid #2c4a86;
    border-radius: 10px;
    padding: 8px 14px;
    font: 700 14px var(--sans);
    cursor: pointer;
}
@media (max-width: 960px) {
    .sidebar {
        transform: translateX(-100%);
        transition: transform 0.2s;
        box-shadow: 0 0 40px rgba(0, 0, 0, 0.6);
    }
    .sidebar.open {
        transform: none;
    }
    .sidebar-toggle {
        display: block;
    }
    .main {
        margin-left: 0;
        padding: 64px 16px 60px;
    }
    .hero {
        padding: 22px 18px;
    }
    .hero-title {
        font-size: 23px;
    }
    .meta-item {
        padding: 8px 0;
        border-right: 0;
        border-bottom: 1px solid var(--border);
        width: 100%;
    }
    .meta-item:last-child {
        border-bottom: 0;
    }
    h2 {
        font-size: 21px;
    }
}
.meta-item:first-child {
    flex: 1 1 100%;
    border-right: 0;
    padding-bottom: 12px;
}
.meta-item:nth-child(2) {
    padding-left: 0;
}
